"use client";
import {useState,useTransition} from "react";
import {useRouter} from "next/navigation";
import Link from "next/link";
import {createStaffMember,updateStaffMember,updateStaffServices,saveStaffAvailability,addStaffOverride,removeStaffOverride,assignBookingStaff,type getVendorStaff} from "@/app/actions/staff";
import {ymdInTrinidad} from "@/lib/timezone/trinidad";
import {bookingDateLabel as orderDate} from "@/lib/services/upcoming-bookings";
import type {AssignmentBooking} from "./StaffWorkspace";
import s from "@/components/vendor/business-workspace.module.css";
type Member=Awaited<ReturnType<typeof getVendorStaff>>[number];
const DAYS=[{id:1,name:"Monday"},{id:2,name:"Tuesday"},{id:3,name:"Wednesday"},{id:4,name:"Thursday"},{id:5,name:"Friday"},{id:6,name:"Saturday"},{id:0,name:"Sunday"}];
function MemberEditor({member,services}:{member:Member;services:{id:string;name:string}[]}){
 const router=useRouter(),[pending,startTransition]=useTransition(),[message,setMessage]=useState(""),[error,setError]=useState("");
 function run(work:()=>Promise<{error?:string;ok?:boolean}>,success:string){setError("");setMessage("");startTransition(async()=>{try{const result=await work();if(result.error){setError(result.error);return;}setMessage(success);router.refresh();}catch{setError("Could not save these changes. Please try again.");}});}
 return <details className={s.card} data-tour="staff-member"><summary className={s.row} style={{cursor:"pointer"}}><span><strong>{member.name}</strong><span className={s.muted} style={{display:"block",marginTop:4}}>{member.services.length} services · {member.availability.filter(d=>d.isActive).length} working days</span></span><span className={s.badge}>{member.isActive?"Active":"Inactive"}</span></summary>
  <div className={s.stack} style={{marginTop:22}}>{error&&<p role="alert" className={s.error}>{error}</p>}{message&&<p role="status" className={s.muted}>{message}</p>}
  <form className={s.stack} style={{gap:12}} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(()=>updateStaffMember(member.id,{name:String(f.get("name")),bio:String(f.get("bio"))}),"Profile saved.");}}><label className={s.label}>Name<input className={s.input} style={{display:"block",width:"100%",marginTop:6}} name="name" defaultValue={member.name} maxLength={100} required/></label><label className={s.label}>About this team member<textarea name="bio" className={s.textarea} defaultValue={member.bio??""} maxLength={1000} rows={2}/></label><div className={s.row}><button disabled={pending} className={s.secondary}>Save profile</button><button type="button" disabled={pending} className={s.link} onClick={()=>run(()=>updateStaffMember(member.id,{isActive:!member.isActive}),member.isActive?"Team member deactivated. Existing bookings remain assigned; review them below.":"Team member activated.")}>{member.isActive?"Deactivate":"Activate"}</button></div></form>
  <form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(()=>updateStaffServices(member.id,f.getAll("services").map(String)),"Service assignments saved.");}}><h3 className={s.heading}>Services they provide</h3><div className={s.stack} style={{gap:10,margin:"12px 0"}}>{services.map(service=><label key={service.id} className={s.muted}><input type="checkbox" name="services" value={service.id} defaultChecked={member.services.some(v=>v.serviceId===service.id)}/> {service.name}</label>)}{!services.length&&<p className={s.muted}>Create a service first.</p>}</div><button disabled={pending} className={s.secondary}>Save services</button></form>
  <form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const schedule=DAYS.map(day=>({dayOfWeek:day.id,isActive:f.has(`active-${day.id}`),startTime:String(f.get(`start-${day.id}`)),endTime:String(f.get(`end-${day.id}`)),slotDurationMins:member.availability.find(d=>d.dayOfWeek===day.id)?.slotDurationMins??60,slotBufferMins:Number(f.get(`buffer-${day.id}`))}));run(()=>saveStaffAvailability(member.id,schedule),"Working hours saved. Existing appointments remain in place.");}}><h3 className={s.heading}>Weekly working hours</h3><p className={s.muted}>Used to check manual staff assignments. Customers book the hours in Service availability.</p>{DAYS.map(day=>{const saved=member.availability.find(d=>d.dayOfWeek===day.id);return <div key={day.id} className={s.divider}><label className={s.muted}><input type="checkbox" name={`active-${day.id}`} defaultChecked={saved?.isActive??false}/> {day.name}</label><div className={s.toolbar} style={{margin:"8px 0 0"}}><label className={s.small}>From <input aria-label={`${day.name} start`} type="time" className={s.input} style={{minWidth:110,width:130}} name={`start-${day.id}`} defaultValue={saved?.startTime??"09:00"} required/></label><label className={s.small}>To <input aria-label={`${day.name} end`} type="time" className={s.input} style={{minWidth:110,width:130}} name={`end-${day.id}`} defaultValue={saved?.endTime??"17:00"} required/></label><label className={s.small}>Buffer (min) <input aria-label={`${day.name} buffer minutes`} type="number" min={0} max={120} className={s.input} style={{width:80,minWidth:60}} name={`buffer-${day.id}`} defaultValue={saved?.slotBufferMins??0}/></label></div></div>;})}<button disabled={pending} className={s.button} style={{marginTop:16}}>Save working hours</button></form>
  <section><h3 className={s.heading}>Time off</h3><p className={s.muted}>Block a date from new staff assignments. Existing appointments are kept for you to reassign.</p>{member.overrides.filter(v=>new Date(v.date).toISOString().slice(0,10)>=ymdInTrinidad()).map(v=><div className={s.divider} key={v.id}><div className={s.row}><span className={s.muted}>{new Date(v.date).toLocaleDateString("en-TT",{timeZone:"UTC",dateStyle:"medium"})} · {v.isBlocked?"Unavailable":`${v.customStartTime}–${v.customEndTime}`} {v.reason&&`· ${v.reason}`}</span><button disabled={pending} className={s.link} onClick={()=>run(()=>removeStaffOverride(v.id),"Date override removed.")}>Remove</button></div></div>)}<form className={s.toolbar} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(()=>addStaffOverride(member.id,{date:String(f.get("date")),isBlocked:true,reason:String(f.get("reason"))}),"Date blocked.");}}><input aria-label={`Time off date for ${member.name}`} type="date" name="date" min={ymdInTrinidad()} className={s.input} required/><input aria-label="Time off reason" name="reason" className={s.input} placeholder="Reason (optional)" maxLength={300}/><button disabled={pending} className={s.secondary}>Block date</button></form></section>
  </div>
 </details>;
}
export default function TeamWorkspace({initialStaff,services,bookings}:{initialStaff:Member[];services:{id:string;name:string}[];bookings:AssignmentBooking[]}){
 const router=useRouter(),[pending,startTransition]=useTransition(),[error,setError]=useState(""),[message,setMessage]=useState(""),[name,setName]=useState("");
 function run(work:()=>Promise<{error?:string;ok?:boolean}>,success:string){setError("");setMessage("");startTransition(async()=>{try{const result=await work();if(result.error){setError(result.error);return;}setMessage(success);router.refresh();}catch{setError("Could not save. Please try again.");}});}
 return <div className={s.stack}>
 <div className={s.hero}><h2 className={s.heading}>A clear plan for the people behind your service.</h2><p className={s.muted}>Add yourself or your team, choose the services each person provides and set working hours. Assign upcoming appointments below. These profiles do not grant dashboard access.</p></div>
 {error&&<p className={s.error} role="alert">{error}</p>}{message&&<p className={s.muted} role="status">{message}</p>}
 <section className={s.card}><div className={s.row}><h2 className={s.heading}>Your team · {initialStaff.filter(m=>m.isActive).length} active</h2></div><form className={s.toolbar} onSubmit={e=>{e.preventDefault();run(async()=>{const result=await createStaffMember({name});if("ok"in result)setName("");return result;},"Team member added. Set their services and working hours below.");}}><input aria-label="New team member name" className={s.input} value={name} onChange={e=>setName(e.target.value)} placeholder="Team member's name" maxLength={100} required/><button className={s.button} disabled={pending||!name.trim()}>Add team member</button></form></section>
 {initialStaff.map(member=><MemberEditor key={member.id+member.availability.map(v=>v.updatedAt).join()+member.services.map(v=>v.serviceId).join()} member={member} services={services}/>)}
 <section className={s.card} data-tour="staff-assignments"><h2 className={s.heading}>Upcoming appointments</h2><p className={s.muted}>Showing the next {bookings.length} appointments, up to 100. Assignments check service eligibility, working hours, time off and overlapping appointments.</p>{bookings.length?bookings.map(b=><form key={b.id} className={s.divider} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run(()=>assignBookingStaff(b.id,String(f.get("staff"))||null),"Appointment assignment saved.");}}><div className={s.row}><div><Link className={s.heading} style={{fontSize:15}} href={`/dashboard/vendor/orders/service/booking/${b.id}`}>{b.product.name} ↗</Link><p className={s.muted}>{orderDate(b.bookingDate)} · {b.startTime}–{b.endTime} · {b.id.slice(-8).toUpperCase()}</p></div><div className={s.toolbar} style={{margin:0}}><select key={b.staffMemberId} aria-label={`Assigned team member for ${b.product.name} ${b.id.slice(-8)}`} name="staff" defaultValue={b.staffMemberId??""} className={s.select}><option value="">Unassigned</option>{initialStaff.filter(m=>m.id===b.staffMemberId||m.isActive&&m.services.some(v=>v.serviceId===b.productId)).map(m=><option value={m.id} key={m.id}>{m.name}{!m.isActive?" (inactive)":""}</option>)}</select><button className={s.secondary} disabled={pending}>Save assignment</button></div></div></form>):<p className={s.empty}>New upcoming bookings will appear here.</p>}</section>
 </div>;
}
